    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    max_prev = max(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.15)

    bid = avg_prev * 1.05
    return min(my_status['budget'], max(bid, 45.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    supply = day_context['supply']
    supply_factor = 1.0 + (1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)) * 0.3  # higher when low supply
    hp = my_status['hp']
    budget = my_status['budget']

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if hp <= 2:
            target_bid = max(DAILY_SALARY * 0.85, max_prev + 2.0)
        elif hp >= 5:
            target_bid = min(DAILY_SALARY * 0.4, max_prev * 0.6)
        else:
            target_bid = min(DAILY_SALARY * 0.6, max_prev * 0.8)
    else:
        if hp <= 2:
            target_bid = DAILY_SALARY * 0.9
        elif hp >= 5:
            target_bid = DAILY_SALARY * 0.35
        else:
            target_bid = DAILY_SALARY * 0.5

    target_bid *= supply_factor
    target_bid = max(0.0, min(budget, target_bid))
    return target_bid
